INSERT INTO `ia_mensagem` (`id_mensagem`, `id_conversa`, `papel`, `conteudo`, `criada_em`, `tokens_entrada`, `tokens_saida`) VALUES
(1, 1, 'usuario', 'salve', '2026-09-05 22:12:48', NULL, NULL),
(2, 1, 'assistente', 'Salve, teste! Como posso ajudar você e a teste hoje? Quer falar sobre metas, vendas, Instagram ou outra coisa do negócio?', '2026-09-05 22:12:48', 455, 46),
(3, 2, 'usuario', 'oq vc tem para me falar?', '2026-09-05 22:15:15', NULL, NULL),
(4, 2, 'assistente', 'Olha só, teste — vou separar em fatos (o que os dados mostram), interpretação curta e próximos passos práticos e viáveis.\n\nFatos observados\n- Conta conectada: teste_coroa; seguidores: 3; publicações totais: 2 (últimos 30 dias: 2).\n- Alcance diário recente registrado: 0 em 2026-09-04 e 2026-09-05 (dados disponíveis são poucos).\n- Publicações recentes (ambas FEED, mesmo dia 2026-08-29):\n  - Post A (17:08): alcance 5, curtidas 2, comentários 3, interações 5, taxa de engajamento por seguidor 166,67%.\n  - Post B (22:20): alcance 5, curtidas 2, comentários 0, interações 2, taxa 66,67%.\n- Resumo calculado:\n  - Amostra de 2 publicações; média de interações 3,5; taxa média de engajamento por seguidor 116,67%.\n  - Melhor post na amostra: Post A; pior: Post B.\n  - Frequência aproximada: 0,5 publicações por semana.\n- Observação dos dados: amostra pequena; comparações usam só publicações/dias disponíveis.\n\nInterpretação (clareza entre dado e leitura)\n- Dado: taxas de engajamento elevadas (em %), porque há muito poucas pessoas acompanhando (3 seguidores). Interpretação: porcentagens altas não significam alcance real ainda — cometem efeito de pequena base de seguidores.\n- Dado: ambos os posts alcançaram 5 contas; comentários maiores no Post A. Interpretação: legendas ou conteúdo do Post A gerou mais conversa; formato FEED funciona na amostra, mas só foram analisadas publicações desse tipo.\n- Dado: alcance diário recente mostra zeros e poucas datas. Interpretação: não há dados suficientes para afirmar tendência de crescimento ou queda de alcance.\n\nPróximos passos — 4 ações prioritárias e simples\n1. Postar com regularidade mínima: 2 posts por semana por 4 semanas para aumentar amostra e engajamento (a frequência atual é ~0,5/sem).  \n2. Repetir formato/estilo do Post A (legenda que estimule comentários) e incluir uma chamada clara para ação (ex.: pergunta no final) para gerar mais comentários.  \n3. Usar hashtags locais e do segmento (3–7 relevantes) e marcar localização Mauá para aumentar alcance local.  \n4. Monitorar e registrar por 30 dias: número de seguidores, alcance por post, curtidas, comentários e compartilhamentos. Traga esses números depois para eu analisar e indicar próximos passos.\n\nO que falta (isto é importante)\n- Dados de impressões, alcance histórico mais longo, alcance por dia contínuo e dados sobre stories/reels. Com isso eu poderia dizer se há crescimento orgânico e qual formato é melhor.\n\nQuer que eu monte 4 legendas com chamadas para ação parecidas com o Post A?', '2026-09-05 22:15:15', 1177, 668),
(5, 2, 'usuario', 'oi', '2026-09-05 22:22:03', NULL, NULL),
(6, 2, 'assistente', 'Oi, teste — como posso te ajudar hoje com o Instagram ou com sua meta?', '2026-09-05 22:22:03', 1838, 35),
(7, 2, 'usuario', 'oie', '2026-09-08 22:29:56', NULL, NULL),
(8, 2, 'assistente', 'Oi, teste — como você está? Quer seguir com alguma das opções abaixo ou tem outra coisa em mente?\n1) Revisar as próximas legendas (faço 4 sugestões).  \n2) Plano rápido de 4 semanas de postagens.  \n3) Ajudar a definir público-alvo e hashtags.  \nEscolhe uma opção ou descreve o que precisa.', '2026-09-08 22:29:56', 1922, 94),
(9, 2, 'usuario', 'olá', '2026-09-09 17:53:53', NULL, NULL),
(10, 2, 'assistente', 'Oi, teste — tudo bem? Quer continuar com alguma das opções que sugeri antes (legendas, plano de 4 semanas, público/hashtags) ou tem outra dúvida agora?', '2026-09-09 17:53:53', 2010, 55);

